window.docContents[115].resolve({"/rules/RG1005/#RG1005-limitations":{"contents":"The label is computed from the exact transitive set; a proof that merely could avoid an axiom still carries it until rewritten.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1005: Transitive axioms must fit the selected profile","header":"Limitations and unsupported cases","id":"/rules/RG1005/#RG1005-limitations"},"/rules/RG2004/#RG2004-limitations":{"contents":"Whole-project scope only: the editor is explicitly partial and does not report this rule, and a single-file audit does not either.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2004: Owned coverage must match the exact Lake inventory","header":"Limitations and unsupported cases","id":"/rules/RG2004/#RG2004-limitations"},"/rules/RG4002/#RG4002-limitations":{"contents":"Examples are checked under the declared toolchain only.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4002: Positive examples require warning-free elaboration and admission","header":"Limitations and unsupported cases","id":"/rules/RG4002/#RG4002-limitations"},"/rules/RG5001/#RG5001-limitations":{"contents":"The editor reports this rule only when the module has finished elaborating without errors; a module with elaboration errors gets RG2005 (incomplete) instead.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5001: Claimed modules require module documentation","header":"Limitations and unsupported cases","id":"/rules/RG5001/#RG5001-limitations"},"/versions/#versions":{"contents":"\n\n\n\n\n\n\n\n\n\n","context":"Regula rule reference","header":"Versions and evidence","id":"/versions/#versions"}});